#!/bin/bash
set -eu
# Passwords generated by configure.py are hex, so cannot alter these SQL literals.
case "$SQL_PASSWORD" in (*[!a-f0-9]*|'') echo 'SQL_PASSWORD must be generated hexadecimal' >&2; exit 1;; esac
mariadb --protocol=socket -uroot -p"$MARIADB_ROOT_PASSWORD" <<SQL
CREATE USER 'steeltip_app'@'%' IDENTIFIED BY '$SQL_PASSWORD';
GRANT SELECT ON steeltip.* TO 'steeltip_app'@'%';
GRANT INSERT,UPDATE,DELETE ON steeltip.players TO 'steeltip_app'@'%';
GRANT INSERT,UPDATE,DELETE ON steeltip.tournaments TO 'steeltip_app'@'%';
GRANT INSERT,UPDATE,DELETE ON steeltip.divisions TO 'steeltip_app'@'%';
GRANT INSERT,UPDATE,DELETE ON steeltip.registrations TO 'steeltip_app'@'%';
GRANT INSERT,UPDATE,DELETE ON steeltip.matches TO 'steeltip_app'@'%';
GRANT INSERT,UPDATE,DELETE ON steeltip.legs TO 'steeltip_app'@'%';
GRANT INSERT,UPDATE,DELETE ON steeltip.reviews TO 'steeltip_app'@'%';
GRANT INSERT,UPDATE,DELETE ON steeltip.sessions TO 'steeltip_app'@'%';
GRANT INSERT ON steeltip.users TO 'steeltip_app'@'%';
GRANT INSERT ON steeltip.revisions TO 'steeltip_app'@'%';
GRANT INSERT ON steeltip.results TO 'steeltip_app'@'%';
GRANT INSERT ON steeltip.snapshots TO 'steeltip_app'@'%';
GRANT INSERT ON steeltip.audits TO 'steeltip_app'@'%';
SQL
